WITH valid AS (SELECT id, store_id, order_date, status, channel, amount, discount, shipping_fee, SUBSTRING(status, 1, 4) AS status_prefix FROM orders WHERE order_date > TO_DATE('2023-09-13') AND channel IS NOT NULL) SELECT s.*, top1.method, top1.payment_paid_at FROM valid s JOIN LATERAL (SELECT c.method, c.paid_at AS payment_paid_at FROM payments c WHERE c.order_id = s.id ORDER BY c.paid_at DESC, c.id DESC LIMIT 1) top1 ON TRUE;
